#!/usr/bin/env node
/**
 * Wire src/brand-kit/tokens.json into the build (NOO-46).
 *
 * Reads the canonical design-token JSON, validates that the shape is
 * intact, and emits src/brand-kit/tailwind-theme.css — a Tailwind v4
 * `@theme` block that exposes the brand tokens as Tailwind utilities
 * (e.g. `bg-primary-800`, `text-ink-900`, `font-display`).
 *
 * The CSS file is generated; do not edit by hand. Source of truth is
 * tokens.json (mirror of brand-kit/tokens/tokens.json from NOO-41).
 *
 * Run via package.json `prebuild` step. CI fails the build if JSON
 * cannot parse, an expected key is missing, or the generated CSS
 * differs from what the build would produce on a clean run.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, "..");
const TOKENS_JSON = resolve(ROOT, "src/brand-kit/tokens.json");
const OUT_CSS = resolve(ROOT, "src/brand-kit/tailwind-theme.css");

const tokens = JSON.parse(readFileSync(TOKENS_JSON, "utf8"));

// --- Validate required top-level branches.
const required = ["color", "font", "space", "radius", "shadow", "motion", "measure"];
for (const k of required) {
  if (!(k in tokens)) {
    throw new Error(`tokens.json is missing required branch: ${k}`);
  }
}
// --- Validate a few load-bearing tokens (NOO-41 contract).
const mustExist = [
  ["color", "primary", "800"],   // .cite color, primary CTA
  ["color", "accent", "500"],    // hedge cue
  ["color", "tier", "1", "bg"],
  ["color", "tier", "3", "rule"],
  ["font", "family", "display"],
];
for (const path of mustExist) {
  let cur = tokens;
  for (const seg of path) {
    if (cur[seg] === undefined) throw new Error(`Missing token: ${path.join(".")}`);
    cur = cur[seg];
  }
}

// --- Helpers
// camelCase -> kebab-case (so JSON `onDark` becomes CSS `on-dark`)
const kebab = (s) => s.replace(/([a-z0-9])([A-Z])/g, "$1-$2").toLowerCase();

const tierLines = [];
for (const tier of ["1", "2", "3"]) {
  const t = tokens.color.tier[tier];
  tierLines.push(`  --color-tier-${tier}-bg: ${t.bg.$value};`);
  tierLines.push(`  --color-tier-${tier}-fg: ${t.fg.$value};`);
  tierLines.push(`  --color-tier-${tier}-rule: ${t.rule.$value};`);
}

const tailwindColorLines = [];
for (const group of ["primary", "accent", "ink"]) {
  for (const [step, def] of Object.entries(tokens.color[group])) {
    tailwindColorLines.push(`  --color-${group}-${kebab(step)}: ${def.$value};`);
  }
}
for (const [name, def] of Object.entries(tokens.color.surface)) {
  tailwindColorLines.push(`  --color-surface-${kebab(name)}: ${def.$value};`);
}
for (const sem of ["success", "warn", "danger", "info"]) {
  for (const [step, def] of Object.entries(tokens.color.semantic[sem])) {
    tailwindColorLines.push(`  --color-${sem}-${kebab(step)}: ${def.$value};`);
  }
}

const fontLines = [
  `  --font-display: ${tokens.font.family.display.$value};`,
  `  --font-body: ${tokens.font.family.body.$value};`,
  `  --font-mono: ${tokens.font.family.mono.$value};`,
];
for (const [name, def] of Object.entries(tokens.font.size)) {
  fontLines.push(`  --text-${kebab(name)}: ${def.$value};`);
}

const spaceLines = Object.entries(tokens.space).map(
  ([k, def]) => `  --spacing-${k}: ${def.$value};`,
);

// NOTE: We intentionally do NOT emit a Tailwind --radius-* mapping here.
// App.css already owns --radius-sm/md/lg/xl for the existing shadcn UI;
// emitting brand radii into @theme would clobber the stack-builder's
// rounded utilities. Brand radii are still available as plain CSS
// variables on :root via tokens.css, and the brand-kit components.css
// references them directly (var(--radius-md)). The bare CSS-variable
// path is the contract used by the brand kit components contract.

const generated = `/* =============================================================
 * Tailwind v4 brand-token bridge (auto-generated from tokens.json).
 *
 * Generated by: scripts/build-brand-tokens.mjs
 * Source: src/brand-kit/tokens.json (NOO-46 wiring of NOO-41 tokens)
 *
 * Do not edit by hand. Re-run \`pnpm tokens:build\` (or the prebuild
 * step) after editing tokens.json.
 * ============================================================= */

@theme inline {
${[...tailwindColorLines, ...tierLines, ...fontLines, ...spaceLines].join("\n")}
}
`;

writeFileSync(OUT_CSS, generated);
console.log(`[brand-tokens] validated tokens.json, wrote ${OUT_CSS}`);
console.log(`[brand-tokens] ${tailwindColorLines.length} colors, ${fontLines.length} font/text, ${spaceLines.length} space (radius intentionally not in @theme; see comment)`);
